/** Leading bullets/arrows that decorate a label without being part of it. */
const PREFIX = /^([›»→•·\-\u2013\u2014]\s*)/;

/**
 * Phrases translated at runtime (cached by the translator route) land here so the
 * rest of the app can resolve them exactly like a curated dictionary entry.
 */
const overlay: Partial<Record<Locale, Record<string, string>>> = {};

export function registerTranslations(locale: Locale, entries: Record<string, string>) {
  if (locale === 'en' || !entries) return;
  overlay[locale] = { ...(overlay[locale] || {}), ...entries };
}

function lookup(text: string, locale: Locale): string | null {
  if (locale === 'en') return text;
  const direct = dictionary[text];
  if (direct) return direct[locale as 'fr' | 'ar'];
  const runtime = overlay[locale]?.[text];
  return runtime || null;
}

export function hasTranslation(text: string, locale: Locale) {
  if (locale === 'en') return true;
  const core = text.trim();
  if (lookup(core, locale)) return true;
  const match = core.match(PREFIX);
  return Boolean(match && lookup(core.slice(match[1].length), locale));
}

/**
 * Phrase lookup used by <T> and by the automatic DOM pass.
 *
 * Handles the decorations that markup adds to a label — leading bullets such as
 * "› Explore courses" and the surrounding whitespace of a text node — so the same
 * dictionary entry serves both forms.
 */
export function translateFromDictionary(text: string, locale: Locale): string {
  if (locale === 'en') return text;

  const leading = text.match(/^\s*/)?.[0] ?? '';
  const trailing = text.match(/\s*$/)?.[0] ?? '';
  const core = text.trim();

  const direct = lookup(core, locale);
  if (direct) return `${leading}${direct}${trailing}`;

  const match = core.match(PREFIX);
  if (match) {
    const inner = lookup(core.slice(match[1].length), locale);
    if (inner) return `${leading}${match[1]}${inner}${trailing}`;
  }

  // Labels often end with an apostrophe-s style suffix or punctuation; try without it.
  const trimmed = core.replace(/[:.!?]+$/, '').trim();
  if (trimmed !== core) {
    const loose = lookup(trimmed, locale);
    if (loose) return `${leading}${loose}${trailing}`;
  }

  return text;
}
